        manager.CurrentState=TaskSwitchExperimentState.Idle;Call(support,"LateUpdate");
        Check(SameColor(currentText.color,Color.white),"Idle experiments do not color current");
        manager.CurrentState=TaskSwitchExperimentState.OperatingSource;Set(support,"useCurrentRangeColoring",false);Call(support,"LateUpdate");
        Check(SameColor(currentText.color,Color.white),"Legacy mode remains switch-triggered during ordinary work");
        Set(support,"useCurrentRangeColoring",true);Call(support,"LateUpdate");
        Check(SameColor(currentText.color,coordinateColors.AchievedValueColor),"Enabling current mode during normal work starts feedback immediately");
        manager.PickupWeight=5000;manager.TargetCondition.workPhase=CraneStatusManager.WorkPhase.LiftUp;
        tracker.CurrentMajorPhase=CraneStatusManager.WorkPhase.LiftUp;tracker.CurrentStepDefinition=Step("LiftUp.LoadAcquisition");
        crane.CraneUnit.IsDownwardMovementBlockedByTouchdown=true;magnet.CurrentElectricCurrentA=50;
        manager.CurrentState=TaskSwitchExperimentState.WaitingForConfirmation;manager.Raise("TargetDisplaySwitched");Call(support,"LateUpdate");
        Check(support.IsVisible&&SameColor(currentText.color,coordinateColors.AchievedValueColor),"Actual switch after normal work still uses the pending Target preview and opens support");
        Call(support,"OnDisable");
        Check(SameColor(currentText.color,Color.white),"Disabling restores the original current color");
        var currentHeading=new Text {color=Color.white};Set(support,"currentInputLabel",currentHeading);
        manager.CurrentState=TaskSwitchExperimentState.WaitingForConfirmation;
        manager.PickupWeight=load.Weight=5000;load.HasWeight=manager.HasPickupWeightPreview=true;
        tracker.CurrentMajorPhase=CraneStatusManager.WorkPhase.LiftUp;tracker.CurrentStepDefinition=Step("LiftUp.LoadAcquisition");
        manager.TargetCondition.workPhase=CraneStatusManager.WorkPhase.LiftUp;
        crane.CraneUnit.IsDownwardMovementBlockedByTouchdown=true;crane.CraneUnit.LocalY=-3;
        magnet.CurrentElectricCurrentA=30;magnet.IsElectricCurrentInputReady=true;
        Input.SetAxis(magnet.CurrentSliderAxis,.6f);
        ExperimentPauseManager.ActiveRealtime=2000;Call(support,"OnEnable");manager.Raise("TargetDisplaySwitched");
        Check(SameColor(currentHeading.color,phase.color)&&SameColor(currentText.color,Color.white),"Switch-time current adjustment colors only the heading");
        Call(support,"LateUpdate");
        Check(!Flag(support,"currentLabelFading"),"A nonzero slider held from the previous crane is not new controller movement");
        magnet.AcceptCurrent(31);Call(support,"LateUpdate");
        Check(!Flag(support,"currentLabelFading")&&magnet.CurrentInputSubscriberCount==0,"Accepted-current events alone do not start the controller-based delay");
        Input.SetAxis("OtherSlider",.9f);Call(support,"LateUpdate");
        Check(!Flag(support,"currentLabelFading"),"Movement on another controller axis cannot trigger the heading");
        Input.SetAxis(magnet.CurrentSliderAxis,.605f);Call(support,"LateUpdate");
        Check(!Flag(support,"currentLabelFading"),"Small controller jitter stays below the movement threshold");
        ExperimentPauseManager.IsPaused=true;Input.SetAxis(magnet.CurrentSliderAxis,.8f);Call(support,"LateUpdate");
        Check(!Flag(support,"currentLabelFading"),"Paused controller movement cannot start the delay");
        ExperimentPauseManager.IsPaused=false;Call(support,"LateUpdate");
        Check(!Flag(support,"currentLabelFading"),"Resuming does not count movement made during pause as a new input");
        magnet.IsElectricCurrentInputReady=false;Input.SetAxis(magnet.CurrentSliderAxis,.82f);Call(support,"LateUpdate");
        Check(Flag(support,"currentLabelFading")&&SameColor(currentHeading.color,phase.color),"Controller movement starts the delay even before confirmation and while current rearm is locked");
        Check(magnet.CurrentElectricCurrentA==31,"Detecting raw input does not require changing the displayed or accepted current");
        ExperimentPauseManager.ActiveRealtime=2000.999;Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,phase.color)&&!Flag(support,"currentLabelFadeLogged"),"Full phase color is retained for the first second after controller movement");
        Input.SetAxis(magnet.CurrentSliderAxis,.95f);
        ExperimentPauseManager.ActiveRealtime=2001;Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,phase.color)&&Flag(support,"currentLabelFadeLogged"),"Fade starts at exactly one second and later movement does not restart the delay");
        ExperimentPauseManager.ActiveRealtime=2001.375;Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,Color.Lerp(phase.color,Color.white,.5f)),"Heading is halfway white 0.375 seconds after the delayed fade begins");
        ExperimentPauseManager.IsPaused=true;Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,Color.Lerp(phase.color,Color.white,.5f)),"Pause preserves delayed fade progress");
        ExperimentPauseManager.IsPaused=false;magnet.IsElectricCurrentInputReady=true;magnet.AcceptCurrent(50);
        ExperimentPauseManager.ActiveRealtime=2001.75;Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,Color.white)&&currentHeading.color.a==1&&!Flag(support,"currentLabelHighlighted"),"Heading is opaque white after one second of delay plus 0.75 seconds of fading");
        Check(SameColor(currentText.color,coordinateColors.AchievedValueColor),"Numeric current green is independent of raw controller fade detection");
        magnet.AcceptCurrent(20);Input.SetAxis(magnet.CurrentSliderAxis,.4f);Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,Color.white),"Further controller movement cannot re-highlight the same episode");

        ExperimentPauseManager.ActiveRealtime=2010;manager.Raise("SourceDisplayRestored");
        Check(SameColor(currentHeading.color,phase.color),"Source return captures a fresh controller baseline");
        manager.Raise("SourceOperationResumed");manager.Raise("SourceInputUnlocked");
        ExperimentPauseManager.ActiveRealtime=2013;Call(support,"LateUpdate");
        Check(!root.activeSelf&&SameColor(currentHeading.color,phase.color),"Heading stays highlighted beyond the arrow deadline until controller movement");
        Input.SetAxis(magnet.CurrentSliderAxis,.2f);Call(support,"LateUpdate");
        ExperimentPauseManager.ActiveRealtime=2014.75;Call(support,"LateUpdate");
        Check(!root.activeSelf&&SameColor(currentHeading.color,Color.white),"Delayed controller-triggered fade works after arrows are gone");

        magnet.CurrentElectricCurrentA=50;manager.Raise("TargetDisplaySwitched");
        Check(SameColor(currentHeading.color,Color.white),"An already appropriate current needs no heading cue");
        magnet.CurrentElectricCurrentA=20;Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,Color.white),"Later current changes do not retrospectively arm the switch snapshot");
        crane.CraneUnit.IsDownwardMovementBlockedByTouchdown=false;manager.Raise("TargetDisplaySwitched");
        Check(SameColor(currentHeading.color,Color.white),"A switch requiring lowering first does not request current adjustment yet");
        crane.CraneUnit.IsDownwardMovementBlockedByTouchdown=true;Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,Color.white),"Later touchdown cannot activate a new heading cue");
        load.HasWeight=manager.HasPickupWeightPreview=false;manager.Raise("TargetDisplaySwitched");
        Check(SameColor(currentHeading.color,Color.white),"Unknown current target does not invent an adjustment cue");
        load.HasWeight=manager.HasPickupWeightPreview=true;

        tracker.CurrentMajorPhase=CraneStatusManager.WorkPhase.Place;tracker.CurrentStepDefinition=Step("Place.LoadRelease");
        load.RemainingWeight=0;magnet.CurrentElectricCurrentA=5;Input.SetAxis(magnet.CurrentSliderAxis,.7f);manager.Raise("SourceDisplayRestored");
        Check(SameColor(currentHeading.color,phase.color),"Placement with nonzero current gets the heading cue");
        Input.SetAxis(magnet.CurrentSliderAxis,.6f);Call(support,"LateUpdate");
        Check(Flag(support,"currentLabelFading")&&magnet.CurrentElectricCurrentA==5,"Physical movement toward zero starts the delay while accepted current remains unchanged");
        manager.Raise("SourceDisplayRestored");Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,phase.color)&&!Flag(support,"currentLabelFading"),"New return cancels the pending fade and captures the new slider position");
        Set(support,"currentInputMovementThreshold",.05f);Input.SetAxis(magnet.CurrentSliderAxis,.62f);Call(support,"LateUpdate");
        Check(!Flag(support,"currentLabelFading"),"Inspector movement threshold filters small axis changes");
        Input.SetAxis(magnet.CurrentSliderAxis,.66f);Call(support,"LateUpdate");
        Check(Flag(support,"currentLabelFading"),"Cumulative change from the baseline triggers movement detection");
        Set(support,"supportContent",TaskSwitchSupportContent.PhaseOnly);Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,Color.white)&&!Flag(support,"currentLabelFading"),"Phase-only content clears the pending controller delay");
        Set(support,"supportContent",TaskSwitchSupportContent.InputDirectionOnly);Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,Color.white),"Re-enabling directions does not create another switch snapshot");
        manager.Raise("SourceDisplayRestored");Call(support,"OnDisable");
        Check(SameColor(currentHeading.color,Color.white),"Disable restores white and clears raw-input monitoring");
        manager.CurrentState=TaskSwitchExperimentState.OperatingSource;Call(support,"OnEnable");Call(support,"LateUpdate");
        Check(SameColor(currentHeading.color,Color.white),"Ordinary current coloring never activates the switch-only heading cue");
        manager.Raise("SourceDisplayRestored");manager.Raise("ExperimentCompleted");
        Check(SameColor(currentHeading.color,Color.white),"Experiment completion clears the heading cue");
        Check(manager.Recorded.Exists(s=>s.StartsWith("CurrentInputLabelShown:"))&&
            manager.Recorded.Exists(s=>s.StartsWith("CurrentInputLabelInputStarted:")&&s.Contains("Anchor=ControllerSliderMovement"))&&
            manager.Recorded.Exists(s=>s.StartsWith("CurrentInputLabelFadeStarted:")&&s.Contains("Anchor=ControllerSliderMovementPlusDelay"))&&
            manager.Recorded.Exists(s=>s.StartsWith("CurrentInputLabelHidden:")&&s.Contains("Reason=ControllerInputStarted")),"Heading logs distinguish raw input, delayed fade and completion");
        Call(support,"OnDisable");
        Console.WriteLine("Cognitive support checks passed: "+checks);
    }
}
